module.exports = function redact(obj) {
  const copy = {...obj};
  for (const key of ['token', 'password']) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      copy[key] = '[redacted]';
    }
  }
  return copy;
};

